#!/usr/bin/env python3
# Generated by morzsa via A2A Mesh delegation
"""
Fleet Blackboard (közös állapotréteg) + OpenTelemetry audit trail
=================================================================
A2A Mesh repó implementáció.

Funkciók:
  - Fleet Blackboard: közös, olvasható állapotréteg minden ügynök számára
  - Task Claim: explicit feladat-lefoglalás ütközés nélkül (determinisztikus)
  - P2P állapot-szinkron: minden node saját blackboard-példányt tart,
    de a fleet blackboard-ra vetítve koordinál
  - OpenTelemetry audit trail: span-ek generálása minden claim/release/update
    művelethez (exportálható Tempo/Grafana felé, vagy konzolra)
  - Audit log: ember-olvasható audit trail a koordinátor számára

Futtatás:
  python fleet_blackboard.py            # demo
  python fleet_blackboard.py --server   # HTTP blackboard server
  python fleet_blackboard.py --client   # CLI client demo

Függőségek:
  - opentelemetry-api, opentelemetry-sdk (opcionális; nélküle konzol-audit)
  - requests (client módhoz)
"""

from __future__ import annotations

import argparse
import json
import os
import sys
import threading
import time
import uuid
from dataclasses import dataclass, field, asdict
from datetime import datetime, timezone
from enum import Enum
from http.server import HTTPServer, BaseHTTPRequestHandler
from typing import Any, Dict, List, Optional, Callable
from urllib.request import Request, urlopen
from urllib.error import URLError, HTTPError

# ---------------------------------------------------------------------------
# OpenTelemetry — opcionális; ha nincs telepítve, fallback konzol-audit
# ---------------------------------------------------------------------------

try:
    from opentelemetry import trace
    from opentelemetry.sdk.trace import TracerProvider
    from opentelemetry.sdk.trace.export import (
        BatchSpanProcessor,
        ConsoleSpanExporter,
    )
    from opentelemetry.sdk.resources import Resource

    _OTEL_AVAILABLE = True
except ImportError:
    _OTEL_AVAILABLE = False


def _init_otel(service_name: str = "a2a-mesh-blackboard"):
    """Inicializálja az OpenTelemetry trace providert, ha elérhető."""
    if not _OTEL_AVAILABLE:
        return None
    resource = Resource.create(
        {"service.name": service_name, "service.namespace": "a2a-mesh"}
    )
    provider = TracerProvider(resource=resource)
    exporter = ConsoleSpanExporter()
    provider.add_span_processor(BatchSpanProcessor(exporter))
    trace.set_tracer_provider(provider)
    return trace.get_tracer("fleet-blackboard")


_tracer = _init_otel()


class _NoopSpan:
    """Fallback span amikor az OTel nem elérhető."""

    def set_attribute(self, key: str, value: Any) -> None:
        pass

    def set_status(self, *args, **kwargs) -> None:
        pass

    def record_exception(self, exc: Exception) -> None:
        pass

    def __enter__(self):
        return self

    def __exit__(self, *args):
        return False


def _start_span(name: str, **attrs):
    """Span indítása — OTel vagy noop."""
    if _tracer is not None:
        span = _tracer.start_span(name)
        for k, v in attrs.items():
            span.set_attribute(k, str(v))
        return span
    return _NoopSpan()


# ---------------------------------------------------------------------------
# Adatmodell
# ---------------------------------------------------------------------------


class TaskStatus(str, Enum):
    PENDING = "pending"
    CLAIMED = "claimed"
    RUNNING = "running"
    COMPLETED = "completed"
    FAILED = "failed"
    RELEASED = "released"


@dataclass
class Task:
    task_id: str
    title: str
    description: str = ""
    status: TaskStatus = TaskStatus.PENDING
    claimed_by: Optional[str] = None  # agent_id
    claimed_at: Optional[str] = None
    priority: int = 0
    created_at: str = field(
        default_factory=lambda: datetime.now(timezone.utc).isoformat()
    )
    updated_at: str = field(
        default_factory=lambda: datetime.now(timezone.utc).isoformat()
    )
    result: Optional[Any] = None
    tags: List[str] = field(default_factory=list)
    dependencies: List[str] = field(default_factory=list)

    def to_dict(self) -> Dict[str, Any]:
        d = asdict(self)
        d["status"] = self.status.value
        return d

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "Task":
        data = dict(data)
        if "status" in data and isinstance(data["status"], str):
            data["status"] = TaskStatus(data["status"])
        return cls(**data)


@dataclass
class AgentState:
    """Egy ügynök vetített állapota a fleet blackboard-on."""
    agent_id: str
    name: str
    model: str = ""
    status: str = "idle"  # idle, busy, offline
    current_task: Optional[str] = None
    last_heartbeat: str = field(
        default_factory=lambda: datetime.now(timezone.utc).isoformat()
    )
    capabilities: List[str] = field(default_factory=list)

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "AgentState":
        return cls(**data)


@dataclass
class AuditEntry:
    """Audit trail bejegyzés — ember-olvasható + OTel span-nel párosítva."""
    entry_id: str
    timestamp: str
    agent_id: str
    action: str  # claim, release, update, heartbeat, register, complete, fail
    task_id: Optional[str]
    details: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


# ---------------------------------------------------------------------------
# Fleet Blackboard — közös állapotréteg
# ---------------------------------------------------------------------------


class FleetBlackboard:
    """
    Közös állapotréteg (blackboard pattern).

    Minden ügynök:
      - regisztrálja magát (register)
      - heartbeat-et küld (heartbeat)
      - task-ot claim-el (claim_task) — determinisztikus, lock-al
      - task-ot frissít (update_task)
      - task-ot felszabadít (release_task) vagy befejez (complete_task)
      - olvassa a teljes fleet állapotot (snapshot)

    A blackboard szálbiztos (threading.RLock).
    Minden művelet audit entry-t generál + OTel span-t.
    """

    def __init__(self, node_id: str = "blackboard-0"):
        self.node_id = node_id
        self._lock = threading.RLock()
        self._tasks: Dict[str, Task] = {}
        self._agents: Dict[str, AgentState] = {}
        self._audit_log: List[AuditEntry] = []
        self._global_state: Dict[str, Any] = {}  # szabad-formátú közös state
        self._listeners: List[Callable[[AuditEntry], None]] = []

    # -- Audit --

    def _audit(
        self,
        agent_id: str,
        action: str,
        task_id: Optional[str] = None,
        **details,
    ) -> AuditEntry:
        entry = AuditEntry(
            entry_id=str(uuid.uuid4()),
            timestamp=datetime.now(timezone.utc).isoformat(),
            agent_id=agent_id,
            action=action,
            task_id=task_id,
            details=details,
        )
        with self._lock:
            self._audit_log.append(entry)
            # keep last 10000
            if len(self._audit_log) > 10000:
                self._audit_log = self._audit_log[-5000:]
        for listener in list(self._listeners):
            try:
                listener(entry)
            except Exception:
                pass
        return entry

    def add_listener(self, fn: Callable[[AuditEntry], None]) -> None:
        self._listeners.append(fn)

    # -- Agent management --

    def register_agent(
        self,
        agent_id: str,
        name: str,
        model: str = "",
        capabilities: Optional[List[str]] = None,
    ) -> AgentState:
        with _start_span(
            "agent.register", agent_id=agent_id, name=name
        ) as span:
            with self._lock:
                agent = AgentState(
                    agent_id=agent_id,
                    name=name,
                    model=model,
                    capabilities=capabilities or [],
                )
                self._agents[agent_id] = agent
            self._audit(agent_id, "register", name=name, model=model)
            span.set_attribute("agent.capabilities", ",".join(agent.capabilities))
            return agent

    def heartbeat(self, agent_id: str, status: str = "idle") -> None:
        with _start_span("agent.heartbeat", agent_id=agent_id, status=status):
            with self._lock:
                agent = self._agents.get(agent_id)
                if agent is None:
                    raise KeyError(f"Agent not registered: {agent_id}")
                agent.last_heartbeat = datetime.now(timezone.utc).isoformat()
                agent.status = status
            self._audit(agent_id, "heartbeat", status=status)

    def deregister_agent(self, agent_id: str) -> None:
        with _start_span("agent.deregister", agent_id=agent_id):
            with self._lock:
                self._agents.pop(agent_id, None)
            self._audit(agent_id, "deregister")

    # -- Task management (determinisztikus claim) --

    def add_task(
        self,
        title: str,
        description: str = "",
        priority: int = 0,
        tags: Optional[List[str]] = None,
        dependencies: Optional[List[str]] = None,
        agent_id: str = "coordinator",
    ) -> Task:
        task_id = f"task-{uuid.uuid4().hex[:12]}"
        task = Task(
            task_id=task_id,
            title=title,
            description=description,
            priority=priority,
            tags=tags or [],
            dependencies=dependencies or [],
        )
        with _start_span(
            "task.add", task_id=task_id, title=title, agent_id=agent_id
        ) as span:
            with self._lock:
                self._tasks[task_id] = task
            self._audit(agent_id, "add_task", task_id, title=title)
            span.set_attribute("task.priority", priority)
        return task

    def claim_task(self, agent_id: str, task_id: str) -> Task:
        """
        Determinisztikus task claim.
        Ha a task már claim-elve van más által → ValueError.
        """
        with _start_span(
            "task.claim", task_id=task_id, agent_id=agent_id
        ) as span:
            with self._lock:
                task = self._tasks.get(task_id)
                if task is None:
                    raise KeyError(f"Task not found: {task_id}")
                if task.status not in (
                    TaskStatus.PENDING,
                    TaskStatus.RELEASED,
                ):
                    if task.claimed_by == agent_id:
                        # re-claim ok
                        pass
                    else:
                        span.set_attribute("claim.conflict", "true")
                        raise ValueError(
                            f"Task {task_id} already claimed by "
                            f"{task.claimed_by} (status={task.status.value})"
                        )
                task.status = TaskStatus.CLAIMED
                task.claimed_by = agent_id
                task.claimed_at = datetime.now(timezone.utc).isoformat()
                task.updated_at = task.claimed_at
                # update agent state
                agent = self._agents.get(agent_id)
                if agent:
                    agent.status = "busy"
                    agent.current_task = task_id
            self._audit(agent_id, "claim", task_id)
            span.set_attribute("claim.success", "true")
            return task

    def start_task(self, agent_id: str, task_id: str) -> Task:
        with _start_span("task.start", task_id=task_id, agent_id=agent_id):
            with self._lock:
                task = self._tasks.get(task_id)
                if task is None:
                    raise KeyError(f"Task not found: {task_id}")
                if task.claimed_by != agent_id:
                    raise PermissionError(
                        f"Agent {agent_id} does not own task {task_id}"
                    )
                task.status = TaskStatus.RUNNING
                task.updated_at = datetime.now(timezone.utc).isoformat()
            self._audit(agent_id, "start", task_id)
            return task

    def update_task(
        self,
        agent_id: str,
        task_id: str,
        status: Optional[TaskStatus] = None,
        result: Optional[Any] = None,
        description: Optional[str] = None,
    ) -> Task:
        with _start_span("task.update", task_id=task_id, agent_id=agent_id):
            with self._lock:
                task = self._tasks.get(task_id)
                if task is None:
                    raise KeyError(f"Task not found: {task_id}")
                if task.claimed_by != agent_id:
                    raise PermissionError(
                        f"Agent {agent_id} does not own task {task_id}"
                    )
                if status is not None:
                    task.status = status
                if result is not None:
                    task.result = result
                if description is not None:
                    task.description = description
                task.updated_at = datetime.now(timezone.utc).isoformat()
            self._audit(
                agent_id,
                "update",
                task_id,
                status=task.status.value if status else None,
            )
            return task

    def complete_task(
        self, agent_id: str, task_id: str, result: Any = None
    ) -> Task:
        with _start_span("task.complete", task_id=task_id, agent_id=agent_id):
            with self._lock:
                task = self._tasks.get(task_id)
                if task is None:
                    raise KeyError(f"Task not found: {task_id}")
                if task.claimed_by != agent_id:
                    raise PermissionError(
                        f"Agent {agent_id} does not own task {task_id}"
                    )
                task.status = TaskStatus.COMPLETED
                task.result = result
                task.updated_at = datetime.now(timezone.utc).isoformat()
                agent = self._agents.get(agent_id)
                if agent:
                    agent.status = "idle"
                    agent.current_task = None
            self._audit(agent_id, "complete", task_id, result=str(result))
            return task

    def fail_task(
        self, agent_id: str, task_id: str, error: str = ""
    ) -> Task:
        with _start_span("task.fail", task_id=task_id, agent_id=agent_id):
            with self._lock:
                task = self._tasks.get(task_id)
                if task is None:
                    raise KeyError(f"Task not found: {task_id}")
                if task.claimed_by != agent_id:
                    raise PermissionError(
                        f"Agent {agent_id} does not own task {task_id}"
                    )
                task.status = TaskStatus.FAILED
                task.result = {"error": error}
                task.updated_at = datetime.now(timezone.utc).isoformat()
                agent = self._agents.get(agent_id)
                if agent:
                    agent.status = "idle"
                    agent.current_task = None
            self._audit(agent_id, "fail", task_id, error=error)
            return task

    def release_task(self, agent_id: str, task_id: str) -> Task:
        """Task felszabadítása — visszakerül PENDING állapotba."""
        with _start_span("task.release", task_id=task_id, agent_id=agent_id):
            with self._lock:
                task = self._tasks.get(task_id)
                if task is None:
                    raise KeyError(f"Task not found: {task_id}")
                if task.claimed_by != agent_id:
                    raise PermissionError(
                        f"Agent {agent_id} does not own task {task_id}"
                    )
                task.status = TaskStatus.RELEASED
                task.claimed_by = None
                task.claimed_at = None
                task.updated_at = datetime.now(timezone.utc).isoformat()
                agent = self._agents.get(agent_id)
                if agent:
                    agent.status = "idle"
                    agent.current_task = None
            self._audit(agent_id, "release", task_id)
            return task

    # -- Global state (szabad-formátú közös state) --

    def set_state(self, key: str, value: Any, agent_id: str = "system") -> None:
        with _start_span("state.set", key=key, agent_id=agent_id):
            with self._lock:
                self._global_state[key] = {
                    "value": value,
                    "set_by": agent_id,
                    "set_at": datetime.now(timezone.utc).isoformat(),
                }
            self._audit(agent_id, "state_set", None, key=key)

    def get_state(self, key: str) -> Optional[Any]:
        with self._lock:
            entry = self._global_state.get(key)
            return entry["value"] if entry else None

    # -- Snapshot (a fő ügynök kivetített fleet blackboard-ja) --

    def snapshot(self) -> Dict[str, Any]:
        """Teljes fleet állapot — mindenki olvashatja."""
        with self._lock:
            return {
                "node_id": self.node_id,
                "timestamp": datetime.now(timezone.utc).isoformat(),
                "agents": {
                    aid: a.to_dict() for aid, a in self._agents.items()
                },
                "tasks": {
                    tid: t.to_dict() for tid, t in self._tasks.items()
                },
                "global_state": dict(self._global_state),
                "stats": {
                    "total_tasks": len(self._tasks),
                    "pending": sum(
                        1
                        for t in self._tasks.values()
                        if t.status == TaskStatus.PENDING
                    ),
                    "claimed": sum(
                        1
                        for t in self._tasks.values()
                        if t.status == TaskStatus.CLAIMED
                    ),
                    "running": sum(
                        1
                        for t in self._tasks.values()
                        if t.status == TaskStatus.RUNNING
                    ),
                    "completed": sum(
                        1
                        for t in self._tasks.values()
                        if t.status == TaskStatus.COMPLETED
                    ),
                    "failed": sum(
                        1
                        for t in self._tasks.values()
                        if t.status == TaskStatus.FAILED
                    ),
                    "active_agents": sum(
                        1
                        for a in self._agents.values()
                        if a.status != "offline"
                    ),
                },
            }

    def get_audit_log(self, limit: int = 100) -> List[Dict[str, Any]]:
        with self._lock:
            return [e.to_dict() for e in self._audit_log[-limit:]]

    def get_pending_tasks(self) -> List[Task]:
        with self._lock:
            return [
                t
                for t in self._tasks.values()
                if t.status in (TaskStatus.PENDING, TaskStatus.RELEASED)
            ]

    def to_json(self) -> str:
        return json.dumps(self.snapshot(), indent=2, default=str)


# ---------------------------------------------------------------------------
# P2P sync — egyszerű HTTP protokoll a blackboard replikációjára
# ---------------------------------------------------------------------------


class BlackboardHTTPHandler(BaseHTTPRequestHandler):
    """HTTP handler a fleet blackboard eléréséhez."""

    blackboard: FleetBlackboard = None  # class-level, set by server factory

    def _send_json(self, code: int, data: Any) -> None:
        body = json.dumps(data, default=str).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _read_body(self) -> dict:
        length = int(self.headers.get("Content-Length", 0))
        if length == 0:
            return {}
        raw = self.rfile.read(length)
        return json.loads(raw)

    def do_GET(self) -> None:
        bb = self.blackboard
        path = self.path.rstrip("/")
        if path == "/snapshot":
            self._send_json(200, bb.snapshot())
        elif path == "/audit":
            self._send_json(200, bb.get_audit_log(200))
        elif path == "/tasks/pending":
            self._send_json(
                200, [t.to_dict() for t in bb.get_pending_tasks()]
            )
        elif path.startswith("/state/"):
            key = path[len("/state/"):]
            val = bb.get_state(key)
            self._send_json(200, {"key": key, "value": val})
        elif path == "/health":
            self._send_json(200, {"status": "ok", "node": bb.node_id})
        else:
            self._send_json(404, {"error": "not found"})

    def do_POST(self) -> None:
        bb = self.blackboard
        path = self.path.rstrip("/")
        body = self._read_body()
        try:
            if path == "/agent/register":
                agent = bb.register_agent(
                    agent_id=body["agent_id"],
                    name=body.get("name", body["agent_id"]),
                    model=body.get("model", ""),
                    capabilities=body.get("capabilities", []),
                )
                self._send_json(200, agent.to_dict())
            elif path == "/agent/heartbeat":
                bb.heartbeat(body["agent_id"], body.get("status", "idle"))
                self._send_json(200, {"ok": True})
            elif path == "/agent/deregister":
                bb.deregister_agent(body["agent_id"])
                self._send_json(200, {"ok": True})
            elif path == "/task/add":
                task = bb.add_task(
                    title=body["title"],
                    description=body.get("description", ""),
                    priority=body.get("priority", 0),
                    tags=body.get("tags", []),
                    dependencies=body.get("dependencies", []),
                    agent_id=body.get("agent_id", "coordinator"),
                )
                self._send_json(200, task.to_dict())
            elif path == "/task/claim":
                task = bb.claim_task(body["agent_id"], body["task_id"])
                self._send_json(200, task.to_dict())
            elif path == "/task/start":
                task = bb.start_task(body["agent_id"], body["task_id"])
                self._send_json(200, task.to_dict())
            elif path == "/task/update":
                status = body.get("status")
                if status:
                    status = TaskStatus(status)
                task = bb.update_task(
                    body["agent_id"],
                    body["task_id"],
                    status=status,
                    result=body.get("result"),
                    description=body.get("description"),
                )
                self._send_json(200, task.to_dict())
            elif path == "/task/complete":
                task = bb.complete_task(
                    body["agent_id"],
                    body["task_id"],
                    body.get("result"),
                )
                self._send_json(200, task.to_dict())
            elif path == "/task/fail":
                task = bb.fail_task(
                    body["agent_id"],
                    body["task_id"],
                    body.get("error", ""),
                )
                self._send_json(200, task.to_dict())
            elif path == "/task/release":
                task = bb.release_task(body["agent_id"], body["task_id"])
                self._send_json(200, task.to_dict())
            elif path == "/state/set":
                bb.set_state(
                    body["key"], body["value"], body.get("agent_id", "system")
                )
                self._send_json(200, {"ok": True})
            else:
                self._send_json(404, {"error": "unknown endpoint"})
        except (KeyError, ValueError, PermissionError) as exc:
            self._send_json(400, {"error": str(exc)})
        except Exception as exc:
            self._send_json(500, {"error": str(exc)})

    def log_message(self, fmt, *args):
        # csendes log
        pass


def make_handler(bb: FleetBlackboard):
    """Factory: HTTP handler osztály a megadott blackboard-dal."""
    return type(
        "BoundHandler",
        (BlackboardHTTPHandler,),
        {"blackboard": bb},
    )


def run_server(host: str = "127.0.0.1", port: int = 8765) -> None:
    bb = FleetBlackboard(node_id=f"bb-{port}")
    handler = make_handler(bb)
    server = HTTPServer((host, port), handler)
    print(f"[blackboard] listening on http://{host}:{port}")
    print(f"[blackboard] endpoints: /snapshot /audit /tasks/pending")
    print(f"  POST /agent/register /agent/heartbeat /task/add /task/claim")
    print(f"       /task/start /task/update /task/complete /task/fail")
    print(f"       /task/release /state/set")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\n[blackboard] shutting down")
        server.shutdown()


# ---------------------------------------------------------------------------
# Remote client — P2P blackboard elérés HTTP-n
# ---------------------------------------------------------------------------


class RemoteBlackboardClient:
    """Távoli fleet blackboard kliens (HTTP)."""

    def __init__(self, base_url: str, agent_id: str, name: str = ""):
        self.base_url = base_url.rstrip("/")
        self.agent_id = agent_id
        self.name = name or agent_id
        self._registered = False

    def _post(self, path: str, data: dict) -> dict:
        url = f"{self.base_url}{path}"
        body = json.dumps(data).encode("utf-8")
        req = Request(
            url,
            data=body,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urlopen(req, timeout=10) as resp:
                return json.loads(resp.read())
        except HTTPError as exc:
            err_body = exc.read().decode("utf-8", "replace")
            raise RuntimeError(f"HTTP {exc.code}: {err_body}") from exc
        except URLError as exc:
            raise RuntimeError(f"Connection error: {exc}") from exc

    def _get(self, path: str) -> dict:
        url = f"{self.base_url}{path}"
        with urlopen(url, timeout=10) as resp:
            return json.loads(resp.read())

    def register(self, model: str = "", capabilities: Optional[List[str]] = None) -> dict:
        result = self._post(
            "/agent/register",
            {
                "agent_id": self.agent_id,
                "name": self.name,
                "model": model,
                "capabilities": capabilities or [],
            },
        )
        self._registered = True
        return result

    def heartbeat(self, status: str = "idle") -> None:
        self._post("/agent/heartbeat", {"agent_id": self.agent_id, "status": status})

    def add_task(self, title: str, **kw) -> dict:
        kw["agent_id"] = self.agent_id
        kw["title"] = title
        return self._post("/task/add", kw)

    def claim_task(self, task_id: str) -> dict:
        return self._post("/task/claim", {"agent_id": self.agent_id, "task_id": task_id})

    def start_task(self, task_id: str) -> dict:
        return self._post("/task/start", {"agent_id": self.agent_id, "task_id": task_id})

    def complete_task(self, task_id: str, result: Any = None) -> dict:
        return self._post(
            "/task/complete",
            {"agent_id": self.agent_id, "task_id": task_id, "result": result},
        )

    def fail_task(self, task_id: str, error: str = "") -> dict:
        return self._post(
            "/task/fail",
            {"agent_id": self.agent_id, "task_id": task_id, "error": error},
        )

    def release_task(self, task_id: str) -> dict:
        return self._post("/task/release", {"agent_id": self.agent_id, "task_id": task_id})

    def snapshot(self) -> dict:
        return self._get("/snapshot")

    def pending_tasks(self) -> list:
        return self._get("/tasks/pending")

    def audit_log(self) -> list:
        return self._get("/audit")

    def set_state(self, key: str, value: Any) -> dict:
        return self._post("/state/set", {"key": key, "value": value, "agent_id": self.agent_id})


# ---------------------------------------------------------------------------
# Audit trail pretty-printer
# ---------------------------------------------------------------------------


def print_audit(entries: List[Dict[str, Any]]) -> None:
    print("\n=== AUDIT TRAIL ===")
    for e in entries:
        ts = e["timestamp"][11:19]
        agent = e["agent_id"][:12].ljust(12)
        action = e["action"].ljust(12)
        task = (e.get("task_id") or "-")[:18].ljust(18)
        details = ""
        if e.get("details"):
            details = " ".join(f"{k}={v}" for k, v in e["details"].items() if v)
        print(f"  {ts}  {agent} {action} {task} {details}")
    print(f"  ({len(entries)} entries)")


def print_snapshot(snap: Dict[str, Any]) -> None:
    print("\n=== FLEET BLACKBOARD SNAPSHOT ===")
    print(f"  node: {snap['node_id']}  ts: {snap['timestamp'][:19]}")
    stats = snap["stats"]
    print(
        f"  tasks: {stats['total_tasks']} "
        f"(pending={stats['pending']} claimed={stats['claimed']} "
        f"running={stats['running']} completed={stats['completed']} "
        f"failed={stats['failed']})"
    )
    print(f"  active agents: {stats['active_agents']}")
    print("\n  Agents:")
    for aid, a in snap["agents"].items():
        ct = a.get("current_task") or "-"
        print(
            f"    {aid[:16].ljust(16)} {a['name'][:16].ljust(16)} "
            f"status={a['status']:<6} task={ct[:16]}"
        )
    print("\n  Tasks:")
    for tid, t in snap["tasks"].items():
        cb = (t.get("claimed_by") or "-")[:12]
        print(
            f"    {tid[:18].ljust(18)} {t['status']:<10} "
            f"by={cb:<12} {t['title'][:40]}"
        )
    if snap.get("global_state"):
        print("\n  Global State:")
        for k, v in snap["global_state"].items():
            print(f"    {k} = {v['value']}")


# ---------------------------------------------------------------------------
# Demo: több-modell/ügynök együttműködés
# ---------------------------------------------------------------------------


def demo_local() -> None:
    """
    Lokális demo: 3 ügynök (Fred, multi-modell) közösen dolgozik feladatokon
    a fleet blackboard-on, determinisztikus claim-el + audit trail-lel.
    """
    print("=" * 70)
    print("Fleet Blackboard Demo — multi-agent coordination")
    print("=" * 70)

    bb = FleetBlackboard(node_id="demo-bb")

    # Audit listener — valós idejű log
    def audit_printer(entry: AuditEntry) -> None:
        ts = entry.timestamp[11:19]
        print(f"  [AUDIT] {ts} {entry.agent_id:<14} {entry.action:<12} "
              f"{entry.task_id or '-'}")

    bb.add_listener(audit_printer)

    # Ügynökök regisztrálása (multi-modell)
    print("\n--- Registering agents ---")
    bb.register_agent("fred-gpt4", "Fred-GPT4", model="gpt-4o", capabilities=["reasoning", "code"])
    bb.register_agent("fred-claude", "Fred-Claude", model="claude-3.5", capabilities=["analysis", "writing"])
    bb.register_agent("fred-local", "Fred-Local", model="llama-3-8b", capabilities=["fast", "summarize"])

    # Koordinátor feladatokat ad hozzá
    print("\n--- Coordinator adding tasks ---")
    t1 = bb.add_task("Analyze dataset", "Run statistical analysis on input.csv", priority=3, tags=["analysis"])
    t2 = bb.add_task("Generate report", "Create summary report from analysis", priority=2, dependencies=[t1.task_id])
    t3 = bb.add_task("Quick summary", "Summarize the report in 3 bullets", priority=1, tags=["fast"])
    t4 = bb.add_task("Code review", "Review generated code for bugs", priority=2, tags=["code"])

    # Közös állapot
    bb.set_state("dataset", "input.csv", agent_id="coordinator")
    bb.set_state("deadline", "2024-12-01T18:00", agent_id="coordinator")

    # Ügynökök claim-elnek — determinisztikus
    print("\n--- Agents claiming tasks ---")
    bb.claim_task("fred-claude", t1.task_id)
    bb.start_task("fred-claude", t1.task_id)

    # Fred-local próbálja claim-elni t1-t → ütközés!
    try:
        bb.claim_task("fred-local", t1.task_id)
    except ValueError as exc:
        print(f"  [CONFLICT] {exc}")

    # Fred-local claim-eli a gyors feladatot
    bb.claim_task("fred-local", t3.task_id)
    bb.start_task("fred-local", t3.task_id)

    # Fred-gpt4 claim-eli a code review-t
    bb.claim_task("fred-gpt4", t4.task_id)
    bb.start_task("fred-gpt4", t4.task_id)

    # Heartbeat-ek
    print("\n--- Heartbeats ---")
    bb.heartbeat("fred-gpt4", "busy")
    bb.heartbeat("fred-claude", "busy")
    bb.heartbeat("fred-local", "busy")

    # Feladatok befejezése
    print("\n--- Completing tasks ---")
    bb.complete_task("fred-claude", t1.task_id, result={"mean": 42.5, "std": 3.1})
    bb.complete_task("fred-local", t3.task_id, result="3-bullet summary done")
    bb.complete_task("fred-gpt4", t4.task_id, result="2 bugs found, 1 minor")

    # t2 most claim-elhető (dependency t1 kész)
    print("\n--- Dependency-aware claim ---")
    bb.claim_task("fred-claude", t2.task_id)
    bb.start_task("fred-claude", t2.task_id)
    bb.complete_task("fred-claude", t2.task_id, result="report.pdf generated")

    # Snapshot
    print_snapshot(bb.snapshot())

    # Audit trail
    print_audit(bb.get_audit_log(200))

    print("\n✓ Demo complete. All tasks processed without collision.")


def demo_client(url: str) -> None:
    """CLI client demo — kapcsolódik egy futó blackboard server-hez."""
    print(f"Connecting to blackboard at {url} ...")
    client = RemoteBlackboardClient(url, agent_id=f"cli-{uuid.uuid4().hex[:6]}", name="CLI-Agent")
    try:
        snap = client.snapshot()
    except Exception as exc:
        print(f"Error: {exc}")
        return

    client.register(model="cli-demo", capabilities=["demo"])
    client.heartbeat("idle")

    # Feladat hozzáadása
    task = client.add_task("CLI demo task", "Added from CLI client", priority=1)
    print(f"Added task: {task['task_id']}")

    # Claim + complete
    client.claim_task(task["task_id"])
    client.complete_task(task["task_id"], result="done via CLI")

    print_snapshot(client.snapshot())
    print_audit(client.audit_log())


